import{_ as a,C as l,c as d,o as r,ai as t,j as o,a as i,G as s}from"./chunks/framework.ERdqLCt_.js";const R=JSON.parse('{"title":"What is a GeoRegion?","description":"","frontmatter":{},"headers":[],"relativePath":"georegions.md","filePath":"georegions.md","lastUpdated":null}'),c={name:"georegions.md"},p={class:"jldocstring custom-block",open:""},g={class:"jldocstring custom-block",open:""},h={class:"jldocstring custom-block",open:""};function u(y,e,G,m,f,b){const n=l("Badge");return r(),d("div",null,[e[9]||(e[9]=t('<h1 id="What-is-a-GeoRegion?" tabindex="-1">What is a GeoRegion? <a class="header-anchor" href="#What-is-a-GeoRegion?" aria-label="Permalink to &quot;What is a GeoRegion? {#What-is-a-GeoRegion?}&quot;">​</a></h1><p>In essence, a <code>GeoRegion</code> is:</p><ul><li><p>a geographical region of interest</p></li><li><p>identified by an <code>ID</code></p></li><li><p>a subregion of a <strong>parent</strong> <code>GeoRegion</code> (identified by <code>pID</code>, which must also be a valid <code>ID</code>)</p></li></ul><div class="tip custom-block"><p class="custom-block-title">Default GeoRegions</p><p>When using GeoRegions.jl, the default <code>GeoRegion</code> should generally be the global domain, specified by <code>GLB</code> and given by the <code>[N,S,E,W]</code> coordinates <code>[90,-90,360,0]</code>. The Global GeoRegion <code>GLB</code> is considered to be a subset of itself.</p></div>',4)),o("details",p,[o("summary",null,[e[0]||(e[0]=o("a",{id:"GeoRegions.AbstractGeoRegion",href:"#GeoRegions.AbstractGeoRegion"},[o("span",{class:"jlbinding"},"GeoRegions.AbstractGeoRegion")],-1)),e[1]||(e[1]=i()),s(n,{type:"info",class:"jlObjectType jlType",text:"Type"})]),e[2]||(e[2]=t('<div class="language-julia vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">julia</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">AbstractGeoRegion</span></span></code></pre></div><p>Abstract supertype for geographical regions. All <code>AbstractGeoRegion</code> types contain the following fields:</p><ul><li><p><code>ID</code> - A <code>String</code> Type, the identifier for the GeoRegion.</p></li><li><p><code>pID</code> - A <code>String</code> Type, the identifier for the parent GeoRegion.</p></li><li><p><code>name</code> - A <code>String</code> Type, the full name of the GeoRegion.</p></li><li><p><code>path</code> - A <code>String</code> Type, the path of the file containing information on this GeoRegion.</p></li><li><p><code>N</code> - A <code>Float</code> Type, contains the northernmost latitude bound.</p></li><li><p><code>S</code> - A <code>Float</code> Type, contains the southernmost latitude bound.</p></li><li><p><code>E</code> - A <code>Float</code> Type, contains the easternmost longitude bound.</p></li><li><p><code>W</code> - A <code>Float</code> Type, contains the westernmost longitude bound.</p></li><li><p><code>θ</code> - A <code>Float</code> Type, the rotation projection for the data in the GeoRegion</p></li><li><p><code>geometry</code> - A <code>Geometry</code> or <code>Vector{Geometry}</code> Type</p></li></ul><p><a href="https://github.com/GeoRegionsEcosystem/GeoRegions.jl/blob/96a71c2656bd1afdc28b0bf6d8ada64d6ef7913e/src/GeoRegions.jl#L28-L42" target="_blank" rel="noreferrer">source</a></p>',4))]),e[10]||(e[10]=t('<h2 id="The-GeoRegion-Type" tabindex="-1">The <code>GeoRegion</code> Type <a class="header-anchor" href="#The-GeoRegion-Type" aria-label="Permalink to &quot;The `GeoRegion` Type {#The-GeoRegion-Type}&quot;">​</a></h2><p>In GeoRegions.jl v8 and above, we have standardized the usage of the struct type <code>GeoRegion</code> for all simple polygonal shapes.</p><p><strong>Current Limitations:</strong></p><ul><li><p>A <code>GeoRegion</code> supports only one shape/polygon per GeoRegion</p></li><li><p>A <code>GeoRegion</code> shape/polygon cannot have holes within it</p></li></ul><p>Work is currently in progress to determine how best to include multiple shapes in a single <code>GeoRegion</code> type.</p><div class="warning custom-block"><p class="custom-block-title"><code>Types</code> of GeoRegions for versions ≤v7</p><p>Previous versions of GeoRegions.jl used to differentiate between Rectilinear (<code>RectRegion</code>) and Polygonal (<code>PolyRegion</code>) Types of GeoRegions. This is no longer supported in ≥v8.</p></div>',6)),o("details",g,[o("summary",null,[e[3]||(e[3]=o("a",{id:"GeoRegions.GeoRegion",href:"#GeoRegions.GeoRegion"},[o("span",{class:"jlbinding"},"GeoRegions.GeoRegion")],-1)),e[4]||(e[4]=i()),s(n,{type:"info",class:"jlObjectType jlType",text:"Type"})]),e[5]||(e[5]=t('<div class="language-julia vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">julia</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">GeoRegion</span></span></code></pre></div><p>A <code>struct</code> containing geometric information on a geographic regions defined in <code>Geometry</code>. We note the following:</p><ul><li><code>geometry</code> - currently is a singular <code>Geometry</code></li></ul><p><a href="https://github.com/GeoRegionsEcosystem/GeoRegions.jl/blob/96a71c2656bd1afdc28b0bf6d8ada64d6ef7913e/src/GeoRegions.jl#L85-L90" target="_blank" rel="noreferrer">source</a></p>',4))]),e[11]||(e[11]=o("h2",{id:"The-Geometry-Type",tabindex:"-1"},[i("The "),o("code",null,"Geometry"),i(" Type "),o("a",{class:"header-anchor",href:"#The-Geometry-Type","aria-label":'Permalink to "The `Geometry` Type {#The-Geometry-Type}"'},"​")],-1)),e[12]||(e[12]=o("p",null,[i("All "),o("code",null,"GeoRegion"),i("s are defined based on a "),o("code",null,"Geometry"),i(" struct type that contains information on the geometry of a GeoRegion.")],-1)),o("details",h,[o("summary",null,[e[6]||(e[6]=o("a",{id:"GeoRegions.Geometry",href:"#GeoRegions.Geometry"},[o("span",{class:"jlbinding"},"GeoRegions.Geometry")],-1)),e[7]||(e[7]=i()),s(n,{type:"info",class:"jlObjectType jlType",text:"Type"})]),e[8]||(e[8]=t('<div class="language-julia vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">julia</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Geometry</span></span></code></pre></div><p>Struct containing the geometry/shape properties of a GeoRegion. All <code>Geometry</code> types contain the following fields:</p><ul><li><p><code>shape</code> - A vector of <code>Point2</code> (see <a href="https://github.com/JuliaGeometry/GeometryBasics.jl" target="_blank" rel="noreferrer">GeometryBasics.jl</a>) Types, defining a non-rectilinear shape of the GeoRegion.</p></li><li><p><code>centroid</code> - A <code>Point2</code> Type, defining the centroid of the GeoRegion.</p></li><li><p><code>polygon</code> - A <code>Polygon</code> Type (see <a href="https://github.com/JuliaGeometry/GeometryBasics.jl" target="_blank" rel="noreferrer">GeometryBasics.jl</a>), which is useful when doing checks on polygons using <a href="https://github.com/JuliaGeo/GeometryOps.jl" target="_blank" rel="noreferrer">GeometryOps.jl</a>.</p></li></ul><p><a href="https://github.com/GeoRegionsEcosystem/GeoRegions.jl/blob/96a71c2656bd1afdc28b0bf6d8ada64d6ef7913e/src/GeoRegions.jl#L59-L66" target="_blank" rel="noreferrer">source</a></p>',4))]),e[13]||(e[13]=o("p",null,[i("GeoRegions.jl extracts the "),o("code",null,"Polygon"),i(" and "),o("code",null,"Vector{Point}"),i(" information from this "),o("code",null,"Geometry"),i(" type and use the functionalities of "),o("a",{href:"https://github.com/JuliaGeo/GeometryOps.jl",target:"_blank",rel:"noreferrer"},"GeometryOps.jl"),i(" to perform checks on polygons.")],-1))])}const _=a(c,[["render",u]]);export{R as __pageData,_ as default};
